<script setup lang="ts">
import {computed,reactive,ref} from 'vue'
import {GraduationCap,Users,Building2,Save,ArrowRight} from '@lucide/vue'
import type {ApiResult,Player,RoomState} from '../types'
import ScholarPortrait from './ScholarPortrait.vue'
import ScholarResume from './ScholarResume.vue'
import type {FacultyCandidate} from '../living-types'
const props=defineProps<{player:Player;state:RoomState;busy:boolean;perform:(a:string,p?:Record<string,unknown>)=>Promise<ApiResult|undefined>}>()
const emit=defineEmits<{students:[]}>(),modes=reactive<Record<string,string>>({}),budgets=reactive<Record<string,number>>({}),rates=reactive<Record<string,number>>({}),cv=ref<FacultyCandidate|null>(null),teamIds=ref<string[]>([]),teamName=ref('空地协同研究团队'),domain=ref('cross'),superviseStudent=ref(''),supervisor=ref('')
const limit=computed(()=>props.state.lab.level>=5?5:props.state.lab.level>=4?3:props.state.lab.level>=3?1:0)
const candidates=computed(()=>(props.player.institute.candidates||[]).filter(c=>!props.player.institute.faculty.some(f=>f.candidateId===c.id)))
const activeStudents=(id:string)=>props.player.students.filter(s=>s.supervisorId===id&&!s.graduatedAt)
const alumni=computed(()=>props.player.living.alumni.filter(a=>a.returnInterested&&!a.returnedAt))
</script>
<template><section class="institute-panel"><header class="v8-heading"><GraduationCap :size="31"/><div><span class="small-label">A GROUP THAT CAN GROW · 有人一起带学生</span><h2>从两位带头人，到一所小小研究所。</h2><p>三级可引进 1 位教师，四级最多 3 位并组建方向团队，五级最多 5 位并开放院士工作站。</p></div></header><div class="v8-summary-strip"><span>已引进教师 <b>{{ player.institute.faculty.length }} / {{ limit }}</b></span><span>方向团队 <b>{{ player.institute.teams.length }}</b></span><span>教师带来的学生岗位 <b>{{ player.institute.faculty.length*2 }}</b></span></div>
 <p v-if="state.lab.level<3" class="v8-lock">升到三级后可以真正招聘教师。每位教师带来两名转入研究生，师生劳务与启动经费都会进入明细。</p>
 <article v-for="f in player.institute.faculty" :key="f.id" class="faculty-dossier"><header><ScholarPortrait :seed="f.id" :size="58" :label="f.name+'头像'"/><div><span class="small-label">{{ f.rank }}</span><h2>{{ f.name }}</h2><p>{{ f.specialty }}</p></div></header><p class="v8-muted">教师劳务 {{ f.salary.rate }} / 小时，离线待发上限 300，累计已发 {{ Math.floor(f.salary.total) }}。学生劳务另行记账。</p><form class="faculty-delegation v8-form" @submit.prevent="perform('institute_delegate',{id:f.id,mode:modes[f.id]||f.delegation,budget:budgets[f.id]??f.budget})"><label>日常培养委托<select :value="modes[f.id]||f.delegation" @change="modes[f.id]=($event.target as HTMLSelectElement).value"><option value="pause">暂由我决定具体任务</option><option value="paper">围绕论文持续培养</option><option value="patent">围绕专利持续培养</option><option value="balanced">论文与专利交替积累</option></select></label><label>每学年版面费授权额度<input type="number" min="0" max="5000" step="1" :value="budgets[f.id]??f.budget" @input="budgets[f.id]=Number(($event.target as HTMLInputElement).value)"/></label><p class="v8-muted">本学年已用 {{ f.spentBudget }} / {{ f.budget }}。额度不预扣；论文完成审稿后才实际付款，0 表示始终等你确认。</p><button class="primary" :disabled="busy"><Save :size="15"/>保存培养委托</button></form><form class="faculty-pay" @submit.prevent="perform('institute_salary',{id:f.id,rate:rates[f.id]??f.salary.rate})"><label>教师劳务 / 小时<input type="number" min="8" max="200" :value="rates[f.id]??f.salary.rate" @input="rates[f.id]=Number(($event.target as HTMLInputElement).value)"/></label><button class="secondary" :disabled="busy">保存教师劳务</button></form><div class="faculty-students"><div v-for="st in activeStudents(f.id)" :key="st.id"><b>{{ st.name }}</b><span>{{ st.degree==='phds'?'博士生':'硕士生' }} · {{ st.topic }}</span><small>{{ st.task?.title||'自主研究' }} · {{ st.moodText }}</small></div></div><button class="text-button" @click="emit('students')">去小课题组看学生详情<ArrowRight :size="14"/></button></article>
 <form v-if="player.institute.faculty.length" class="v8-form faculty-supervision" @submit.prevent="perform('institute_supervise',{studentId:superviseStudent,facultyId:supervisor})"><h3>调整日常指导安排</h3><label>在读同学<select v-model="superviseStudent" required><option value="" disabled>选择一位在读同学</option><option v-for="st in player.students.filter(st=>!st.graduatedAt)" :key="st.id" :value="st.id">{{ st.name }} · {{ st.topic }}</option></select></label><label>日常指导教师<select v-model="supervisor"><option value="">{{ player.name }} · 我来指导</option><option v-for="f in player.institute.faculty" :key="f.id" :value="f.id">{{ f.name }} · 目前 {{ activeStudents(f.id).length }}/2 名</option></select></label><p class="v8-muted">每位教师最多指导两名在读生。日常指导只影响后续共同成果，已发表作品保留原作者。</p><button class="primary" :disabled="busy||!superviseStudent">确认新的指导安排</button></form><div class="section-title"><h2>教师交流与引进</h2><span>先看研究与指导经历</span></div><div class="faculty-candidates"><article v-for="c in candidates" :key="c.id"><ScholarPortrait :seed="c.id+player.id" :size="50" :label="c.name+'头像'"/><div><span class="small-label">{{ c.rank }}</span><h3>{{ c.name }}</h3><p>{{ c.specialty }}</p><small>启动支持 {{ c.cost }} · 教师劳务 {{ c.rate }}/小时 · 转入两位同学</small></div><button class="secondary" @click="cv=c">查看简历</button></article></div>
 <article v-for="a in alumni" :key="a.id" class="v8-note"><h3>{{ a.name }}想回来一起工作</h3><p>{{ a.organization }} · {{ a.topic }}。校友回流启动支持 2400，教师劳务 8/小时。</p><button class="primary" :disabled="busy||state.lab.level<3||player.institute.faculty.length>=limit||player.funds<2400" @click="perform('institute_recruit',{option:'alumni:'+a.id})">支持校友回流任职</button></article>
 <template v-if="state.lab.level>=4"><div class="section-title"><h2>组建研究方向团队</h2><span>每组 2–3 位教师</span></div><form class="v8-form" @submit.prevent="perform('institute_team',{facultyIds:teamIds,name:teamName,domain})"><label>团队名称<input v-model="teamName" maxlength="40" required/></label><label>研究方向<select v-model="domain"><option value="civil">智能建造</option><option value="air">低空经济</option><option value="cross">空地协同</option></select></label><div class="v8-checks"><label v-for="f in player.institute.faculty" :key="f.id"><input v-model="teamIds" type="checkbox" :value="f.id" :disabled="player.institute.teams.some(t=>t.facultyIds.includes(f.id))"/>{{ f.name }}</label></div><p class="v8-muted">建设支出 2000，匹配方向的新横向、企业合作与竞赛准备增加 12% 团队提速。</p><button class="primary" :disabled="busy||teamIds.length<2||teamIds.length>3||player.institute.teams.length>=2||player.funds<2000"><Users :size="15"/>成立研究方向团队</button></form></template><article v-for="t in player.institute.teams" :key="t.id" class="v8-note"><h3>{{ t.name }}</h3><p>{{ t.facultyIds.map(id=>player.institute.faculty.find(f=>f.id===id)?.name).join('、') }}</p></article>
 <article class="workstation-panel"><Building2 :size="29"/><div><h3>{{ player.institute.workstation?.name||'未来城市院士工作站' }}</h3><p>{{ player.institute.workstation?'工作站已成立，可以在联合课题里承接城市级应急研究。':'五级、至少两位教师，投入 20000 建立工作站，开放总经费 36000 的城市级联合任务。' }}</p></div><button v-if="!player.institute.workstation" class="primary" :disabled="busy||state.lab.level<5||player.institute.faculty.length<2||player.funds<20000" @click="perform('institute_workstation')">成立院士工作站</button></article>
 <div v-if="cv" class="resume-overlay" role="dialog" aria-modal="true" :aria-label="cv.name+'教师简历'" @click.self="cv=null" @keydown.esc="cv=null"><section class="resume-dialog"><button class="text-button close-resume" @click="cv=null">返回教师交流册</button><ScholarResume :name="cv.name" :resume="cv.resume" :topic="cv.specialty"/><button class="primary wide" :disabled="busy||state.lab.level<3||player.institute.faculty.length>=limit||player.funds<cv.cost" @click="perform('institute_recruit',{option:cv.id});cv=null">邀请加入 · 启动支持 {{ cv.cost }}</button></section></div>
 </section></template>
